       AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = to_regclass('buying.supplier_reminder_settings') AND conname = 'ck_supplier_reminder_settings_supplier_id_required__required') THEN
        IF EXISTS (SELECT 1 FROM buying.supplier_reminder_settings WHERE NOT ((supplier_id IS NOT NULL AND btrim(supplier_id::text) <> ''))) THEN
            RAISE NOTICE 'ck_supplier_reminder_settings_supplier_id_required__required not added: stored rows of buying.supplier_reminder_settings break it';
        ELSE
            ALTER TABLE buying.supplier_reminder_settings ADD CONSTRAINT ck_supplier_reminder_settings_supplier_id_required__required CHECK ((supplier_id IS NOT NULL AND btrim(supplier_id::text) <> ''));
        END IF;
    END IF;
EXCEPTION WHEN undefined_column THEN
    RAISE NOTICE 'ck_supplier_reminder_settings_supplier_id_required__required not added: buying.supplier_reminder_settings lacks a column it reads';
END $$;

